package com.drivique.api.payments;
import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; import com.drivique.api.model.*; import com.drivique.api.service.PaymentReceiptPdfService; import java.math.BigDecimal; import java.time.Instant; import org.junit.jupiter.api.Test;
class PaymentReceiptPdfServiceTests {@Test void generatesOfficialPdfWithTaxBreakdownAndQr(){Payment payment=mock(Payment.class);RentalContract contract=mock(RentalContract.class);User customer=mock(User.class);PaymentMethod method=mock(PaymentMethod.class);when(payment.getContract()).thenReturn(contract);when(contract.getCustomer()).thenReturn(customer);when(customer.getFullName()).thenReturn("Danna Cliente");when(payment.getPaymentMethod()).thenReturn(method);when(method.getCode()).thenReturn("CASH");when(payment.getGatewayReference()).thenReturn("CASH-001");when(payment.getAmount()).thenReturn(new BigDecimal("119000.00"));when(payment.getPaidAt()).thenReturn(Instant.now());byte[] pdf=new PaymentReceiptPdfService().generate(payment,"RCP-2026-000001");assertThat(pdf).startsWith("%PDF".getBytes()).hasSizeGreaterThan(1000);}}
